import os,re,collections
mods=['pulsar-broker','pulsar-broker-common','pulsar-client','pulsar-client-api','pulsar-common','pulsar-metadata','managed-ledger']
files={}
for m in mods:
    for r,_,fs in os.walk(m+'/src/main/java'):
        for f in fs:
            if f.endswith('.java') and f not in('package-info.java','module-info.java'):
                p=os.path.join(r,f);s=open(p,encoding='utf8',errors='ignore').read()
                mm=re.search(r'^package\s+([\w.]+);',s,re.M)
                if not mm or not mm.group(1).startswith('org.apache.pulsar'):continue
                files[mm.group(1)+'.'+f[:-5]]=(mm.group(1),s)
def strip(s):
    s=re.sub(r'/\*.*?\*/','',s,flags=re.S);s=re.sub(r'//[^\n]*','',s)
    return re.sub(r'"(\\.|[^"\\])*"','""',s)
byname=collections.defaultdict(list)
for fq in files: byname[fq.rsplit('.',1)[1]].append(fq)
cnt=collections.Counter()
for fq,(pkg,s) in files.items():
    s=strip(s)
    imports=set(re.findall(r'^import\s+(?!static)([\w.]+);',s,re.M))
    simp=set(re.findall(r'^import\s+static\s+([\w.]+)\.\w+;',s,re.M))
    wild=set(re.findall(r'^import\s+([\w.]+)\.\*;',s,re.M))
    body=re.sub(r'^(import|package)[^\n]*','',s,flags=re.M)
    toks=set(re.findall(r'[A-Za-z_]\w*',body))
    deps=set()
    for t in toks:
        for c in byname.get(t,[]):
            cp=c.rsplit('.',1)[0]
            if c in imports or c in simp or cp==pkg or cp in wild: deps.add(c)
    # fully qualified inline
    for c in files:
        if c in body: deps.add(c)
    deps.discard(fq)
    for d in deps:cnt[d]+=1
for k,v in cnt.most_common(14):print(k,v)
